functions.showToolManager:
function showToolManager() {
  var out = document.getElementById("output");
  out.innerHTML = "";
  out.classList.remove("hidden");
  out.classList.add("eli-view-enter");
  var header = createConfigHeader("ELI EXTENSIONS", "🧩", "Tool Manager", { marginBottom: "12px" });
  out.appendChild(header);
  var listWrap = document.createElement("div");
  listWrap.style.cssText = "padding:0 16px 16px 16px;";
  out.appendChild(listWrap);
  var actionsWrap = document.createElement("div");
  actionsWrap.style.cssText = "padding:0 16px 20px 16px; display:flex; gap:8px; flex-wrap:wrap;";
  out.appendChild(actionsWrap);
  if (typeof window.createPlatinumHomeBtn === "function") out.appendChild(window.createPlatinumHomeBtn());
  _toolManagerRender(listWrap, actionsWrap);
}

functions._toolManagerRender:
function _toolManagerRender(listWrap, actionsWrap) {
  // Mark wrappers so the auto-update badge refresher can find + re-render
  // this view if it's currently mounted.
  listWrap.setAttribute("data-tm-list", "1");
  actionsWrap.setAttribute("data-tm-actions", "1");
  listWrap.innerHTML = '<div style="padding:14px; text-align:center; font-size:11px; color:#94a3b8;">Loading…</div>';
  Promise.all([loadFeatureData(STORE_JSON_TOOLS), _eliReadEnabledToolIds()]).then(function (results) {
    var rows = results[0] || [];
    var enabledIds = results[1];
    var tools = rows.filter(function (r) { return r && r.id && String(r.id).indexOf("__") !== 0; });
    var meta = rows.filter(function (r) { return r && r.id === "__meta"; })[0];
    var sectionVer = (meta && Number(meta.version || meta.lastSeenVersion || 0)) || 0;
    function isEnabled(id) {
      if (enabledIds === null) return true;
      return enabledIds.indexOf(id) !== -1;
    }
    var enabledCount = tools.filter(function (t) { return isEnabled(t.id); }).length;
    var disabledCount = tools.length - enabledCount;
    var pending = window._eliPendingUpdates || [];
    var pendingById = {};
    pending.forEach(function (p) { pendingById[p.id] = p; });
    var available = window._eliAvailableTools || [];
    var updateCount = pending.length;
    var availableCount = available.length;
    var headerCount =
      '<div style="display:flex; justify-content:space-between; align-items:center; margin-bottom:10px; padding:6px 10px; background:linear-gradient(135deg,#0f172a,#1e293b); color:#fff;">' +
      '<div style="font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px;">' + tools.length + ' installed · ' + enabledCount + ' active' + (disabledCount > 0 ? ' · ' + disabledCount + ' disabled' : '') + (updateCount > 0 ? ' · <span style="color:#fde68a;">' + updateCount + ' update' + (updateCount === 1 ? '' : 's') + '</span>' : '') + (availableCount > 0 ? ' · <span style="color:#86efac;">' + availableCount + ' new</span>' : '') + '</div>' +
      (sectionVer > 0 ? '<div style="font-size:10px; color:#94a3b8;">section v' + sectionVer + '</div>' : '') +
      '</div>';
    var html = headerCount;
    if (tools.length === 0) {
      html +=
        '<div style="padding:24px; text-align:center; font-size:11px; color:#64748b; background:#f8fafc; border:1px dashed #cbd5e1;">' +
        'No tools installed yet. Use <strong>Install new tool</strong> below to upload a tool JSON.' +
        '</div>';
    } else {
      html += tools.map(function (t, idx) {
        var ic = (t.catalog && t.catalog.icon) || "🧩";
        var lab = (t.catalog && t.catalog.title) || t.label || t.id;
        var cat = (t.catalog && t.catalog.category) || "(no category)";
        var desc = (t.catalog && t.catalog.desc) || "";
        var ver = Number(t.__version) || 0;
        var stripe = idx % 2 === 0 ? "#ffffff" : "#f8fafc";
        var on = isEnabled(t.id);
        var dimStyle = on ? "" : "opacity:0.55; filter:grayscale(0.4);";
        var pendingForTool = pendingById[t.id];
        var borderColor = pendingForTool ? "#f59e0b" : (on ? "#1565c0" : "#94a3b8");
        var toggleLabel = on ? "✓ ON" : "🔕 OFF";
        var toggleBg = on ? "#dcfce7" : "#fff";
        var toggleColor = on ? "#166534" : "#64748b";
        var toggleBorder = on ? "#86efac" : "#cbd5e1";
        var updateRow = pendingForTool
          ? '<div style="background:#fffbeb; border-top:1px dashed #fcd34d; padding:6px 10px; margin:8px -12px -10px -12px; display:flex; justify-content:space-between; align-items:center; gap:8px;">' +
              '<div style="flex:1; min-width:0;">' +
                '<div style="font-size:10px; font-weight:800; color:#92400e; text-transform:uppercase; letter-spacing:0.5px;">🆙 v' + ver + ' → v' + pendingForTool.version + ' available</div>' +
                (pendingForTool.changelog ? '<div style="font-size:10px; color:#78350f; margin-top:2px;">' + _ebEsc(pendingForTool.changelog) + '</div>' : '') +
              '</div>' +
              '<button data-tm-update-cdn="' + _ebEsc(t.id) + '" title="Download v' + pendingForTool.version + ' from CDN" style="padding:4px 12px; font-size:10px; cursor:pointer; background:linear-gradient(135deg,#f59e0b,#d97706); color:#fff; border:none; font-weight:800; border-radius:0;">UPDATE</button>' +
            '</div>'
          : '';
        return (
          '<div style="background:' + stripe + '; border:1px solid #e2e8f0; border-left:3px solid ' + borderColor + '; padding:10px 12px; margin-bottom:8px; ' + dimStyle + '">' +
          '<div style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px;">' +
          '<div style="flex:1; min-width:0;">' +
          '<div style="font-size:13px; font-weight:700; color:#0f172a;">' + ic + ' ' + _ebEsc(lab) + (ver > 0 ? ' <span style="font-size:10px; font-weight:500; color:#1565c0;">(v' + ver + ')</span>' : '') + '</div>' +
          '<div style="font-size:10px; color:#64748b; margin-top:2px;">' + _ebEsc(cat) + (desc ? ' · ' + _ebEsc(desc) : '') + '</div>' +
          '</div>' +
          '<div style="display:flex; gap:4px; flex-shrink:0;">' +
          '<button data-tm-toggle="' + _ebEsc(t.id) + '" title="' + (on ? "Disable (won\'t load at boot)" : "Enable (load at next boot)") + '" style="padding:4px 8px; font-size:10px; cursor:pointer; background:' + toggleBg + '; border:1px solid ' + toggleBorder + '; color:' + toggleColor + '; border-radius:0; font-weight:700;">' + toggleLabel + '</button>' +
          '<button data-tm-update="' + _ebEsc(t.id) + '" title="Upload a newer version (manual file)" style="padding:4px 8px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #1565c0; color:#1565c0; border-radius:0;">⬆️</button>' +
          '<button data-tm-export="' + _ebEsc(t.id) + '" title="Download as JSON" style="padding:4px 8px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #0d9488; color:#0d9488; border-radius:0;">📤</button>' +
          '<button data-tm-remove="' + _ebEsc(t.id) + '" title="Uninstall this tool" style="padding:4px 8px; font-size:10px; cursor:pointer; background:#fff; border:1px solid #dc2626; color:#dc2626; border-radius:0;">🗑️</button>' +
          '</div>' +
          '</div>' +
          updateRow +
          '</div>'
        );
      }).join("");
    }
    // === Available to install (new tools in manifest, not yet installed) ===
    if (availableCount > 0) {
      html +=
        '<div style="margin-top:14px; padding:6px 10px; background:linear-gradient(135deg,#064e3b,#065f46); color:#fff; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px;">' +
        '🌱 Available to install (' + availableCount + ')' +
        '</div>';
      html += available.map(function (a, idx) {
        var stripe = idx % 2 === 0 ? "#f0fdf4" : "#ecfdf5";
        return (
          '<div style="background:' + stripe + '; border:1px solid #bbf7d0; border-left:3px solid #16a34a; padding:10px 12px; margin-bottom:8px;">' +
          '<div style="display:flex; justify-content:space-between; align-items:flex-start; gap:8px;">' +
          '<div style="flex:1; min-width:0;">' +
          '<div style="font-size:13px; font-weight:700; color:#0f172a;">🆕 ' + _ebEsc(a.label) + ' <span style="font-size:10px; font-weight:500; color:#16a34a;">(v' + a.version + ')</span></div>' +
          '<div style="font-size:10px; color:#475569; margin-top:2px;">id: ' + _ebEsc(a.id) + (a.changelog ? ' · ' + _ebEsc(a.changelog) : '') + '</div>' +
          '</div>' +
          '<button data-tm-install-new="' + _ebEsc(a.id) + '" title="Install from CDN" style="padding:4px 14px; font-size:10px; cursor:pointer; background:linear-gradient(135deg,#16a34a,#15803d); color:#fff; border:none; font-weight:800; border-radius:0;">INSTALL</button>' +
          '</div>' +
          '</div>'
        );
      }).join("");
    }
    listWrap.innerHTML = html;
    listWrap.querySelectorAll("[data-tm-toggle]").forEach(function (b) {
      b.onclick = function () { _toolManagerToggle(b.getAttribute("data-tm-toggle"), listWrap, actionsWrap); };
    });
    listWrap.querySelectorAll("[data-tm-update]").forEach(function (b) {
      b.onclick = function () { _toolManagerUpdate(b.getAttribute("data-tm-update"), listWrap, actionsWrap); };
    });
    listWrap.querySelectorAll("[data-tm-export]").forEach(function (b) {
      b.onclick = function () { _toolManagerExport(b.getAttribute("data-tm-export"), tools); };
    });
    listWrap.querySelectorAll("[data-tm-remove]").forEach(function (b) {
      b.onclick = function () { _toolManagerRemove(b.getAttribute("data-tm-remove"), listWrap, actionsWrap); };
    });
    listWrap.querySelectorAll("[data-tm-update-cdn]").forEach(function (b) {
      b.onclick = function () { _toolManagerApplyCdnUpdate(b.getAttribute("data-tm-update-cdn"), listWrap, actionsWrap); };
    });
    listWrap.querySelectorAll("[data-tm-install-new]").forEach(function (b) {
      b.onclick = function () { _toolManagerInstallNew(b.getAttribute("data-tm-install-new"), listWrap, actionsWrap); };
    });
    actionsWrap.innerHTML = '';
    var btnInstall = document.createElement("button");
    btnInstall.style.cssText = "flex:1; min-width:140px; padding:10px; font-size:11px; font-weight:700; background:linear-gradient(135deg,#1565c0,#0d47a1); color:#fff; border:1.5px solid #0d47a1; cursor:pointer;";
    btnInstall.innerHTML = "+ Install new tool(s) (file)";
    btnInstall.onclick = function () { _toolManagerInstall(null, listWrap, actionsWrap); };
    actionsWrap.appendChild(btnInstall);
    var btnExportSel = document.createElement("button");
    btnExportSel.style.cssText = "flex:1; min-width:140px; padding:10px; font-size:11px; font-weight:700; background:#fff; color:#0d9488; border:1.5px solid #0d9488; cursor:pointer;";
    btnExportSel.innerHTML = "📦 Export selected as bundle";
    btnExportSel.onclick = function () { _toolManagerExportSelected(tools); };
    actionsWrap.appendChild(btnExportSel);
    var btnExportAll = document.createElement("button");
    btnExportAll.style.cssText = "flex:1; min-width:140px; padding:10px; font-size:11px; font-weight:700; background:#f8fafc; color:#0d9488; border:1px solid #0d9488; cursor:pointer;";
    btnExportAll.innerHTML = "📦 Export all";
    btnExportAll.onclick = function () { _toolManagerExportAll(tools); };
    actionsWrap.appendChild(btnExportAll);
    var btnForceReinstall = document.createElement("button");
    btnForceReinstall.style.cssText = "flex:1; min-width:140px; padding:10px; font-size:11px; font-weight:700; background:#fff; color:#d97706; border:1.5px solid #d97706; cursor:pointer;";
    btnForceReinstall.innerHTML = "🔄 Force reinstall…";
    btnForceReinstall.onclick = function () { _toolManagerForceReinstall(tools); };
    actionsWrap.appendChild(btnForceReinstall);
    // "Update all" appears only when there are pending CDN updates (Check now lives in Settings)
    if (updateCount > 0) {
      var btnAll = document.createElement("button");
      btnAll.style.cssText = "flex:1; min-width:140px; padding:10px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#f59e0b,#d97706); color:#fff; border:none; cursor:pointer; letter-spacing:0.5px;";
      btnAll.innerHTML = "🆙 Update all (" + updateCount + ")";
      btnAll.onclick = function () { _toolManagerApplyAllCdnUpdates(listWrap, actionsWrap); };
      actionsWrap.appendChild(btnAll);
    }
    if (availableCount > 0) {
      var btnInstallAll = document.createElement("button");
      btnInstallAll.style.cssText = "flex:1; min-width:140px; padding:10px; font-size:11px; font-weight:800; background:linear-gradient(135deg,#16a34a,#15803d); color:#fff; border:none; cursor:pointer; letter-spacing:0.5px;";
      btnInstallAll.innerHTML = "🌱 Install all new (" + availableCount + ")";
      btnInstallAll.onclick = function () { _toolManagerInstallAllNew(listWrap, actionsWrap); };
      actionsWrap.appendChild(btnInstallAll);
    }
  });
}

functions._toolManagerUpdate:
function _toolManagerUpdate(toolId, listWrap, actionsWrap) {
  var inp = document.createElement("input");
  inp.type = "file"; inp.accept = ".json"; inp.style.display = "none";
  inp.onchange = function (e) {
    var f = e.target.files && e.target.files[0]; if (!f) return;
    var reader = new FileReader();
    reader.onload = function (evt) {
      var json;
      try { json = JSON.parse(evt.target.result); }
      catch (err) { showToast("⚠️ Invalid JSON: " + (err && err.message ? err.message : "parse error"), "error"); return; }
      var arr = (json && json.sections && Array.isArray(json.sections.jsonTools)) ? json.sections.jsonTools : [];
      var match = arr.filter(function (t) { return t && t.id === toolId; })[0];
      if (!match) {
        showToast("⚠️ JSON doesn't contain a tool with id '" + toolId + "'", "error");
        return;
      }
      loadFeatureData(STORE_JSON_TOOLS).then(function (existing) {
        var byId = {};
        (existing || []).forEach(function (r) { if (r && r.id) byId[r.id] = r; });
        byId[toolId] = match;
        var rows = Object.keys(byId).map(function (k) { return byId[k]; });
        return saveFeatureData(STORE_JSON_TOOLS, rows);
      }).then(function () {
        if (typeof _dataHubSyncToolsToCatalog === "function") return _dataHubSyncToolsToCatalog();
      }).then(function () {
        if (typeof _eliLoadJsonTools === "function") _eliLoadJsonTools();
        showToast("✅ Tool updated: " + toolId, "success");
        _toolManagerRender(listWrap, actionsWrap);
      });
    };
    reader.readAsText(f);
  };
  document.body.appendChild(inp); inp.click();
  setTimeout(function () { try { document.body.removeChild(inp); } catch (_) { } }, 1000);
}

functions._toolManagerExport:
function _toolManagerExport(toolId, tools) {
  var t = tools.filter(function (x) { return x && x.id === toolId; })[0];
  if (!t) { showToast("Tool not found", "error"); return; }
  var payload = {
    schemaVersion: DATA_HUB_SCHEMA_VERSION,
    exportedAt: new Date().toISOString(),
    sectionVersions: { jsonTools: Number(t.__version) || 1 },
    sections: { jsonTools: [t] },
  };
  var fname = "tool-" + toolId + "-" + new Date().toISOString().slice(0, 10) + ".json";
  _dataHubTriggerDownload(fname, JSON.stringify(payload, null, 2));
}

functions._toolManagerExportAll:
function _toolManagerExportAll(tools) {
  if (!tools.length) { showToast("No tools to export", "info"); return; }
  var maxVer = tools.reduce(function (m, t) { return Math.max(m, Number(t.__version) || 0); }, 0);
  var payload = {
    schemaVersion: DATA_HUB_SCHEMA_VERSION,
    exportedAt: new Date().toISOString(),
    manifest: { name: "ELI Tool Bundle", count: tools.length },
    sectionVersions: { jsonTools: maxVer || 1 },
    sections: { jsonTools: tools },
  };
  var fname = "eli-tools-bundle-" + new Date().toISOString().slice(0, 10) + ".json";
  _dataHubTriggerDownload(fname, JSON.stringify(payload, null, 2));
}
// Per-tool checkbox dialog → exports the selection as a single bundle JSON.
// Lets you build a curated bundle (e.g. "DocuScrub + Final Review for Alice")
// without including every installed tool.

functions._toolManagerExportSelected:
function _toolManagerExportSelected(tools) {
  if (!tools.length) { showToast("No tools to export", "info"); return; }
  var rowsHtml = tools.map(function (t) {
    var ic = (t.catalog && t.catalog.icon) || "🧩";
    var lab = (t.catalog && t.catalog.title) || t.label || t.id;
    var cat = (t.catalog && t.catalog.category) || "Uncategorized";
    var ver = Number(t.__version) || 0;
    return '<label style="display:block; padding:7px 10px; cursor:pointer; border-bottom:1px solid #f1f5f9; text-align:left;">' +
      '<input type="checkbox" data-tm-exp-id="' + _ebEsc(t.id) + '" style="margin-right:8px; vertical-align:middle; cursor:pointer;">' +
      '<span style="font-size:12px; font-weight:700; color:#0f172a; vertical-align:middle;">' + ic + ' ' + _ebEsc(lab) + '</span>' +
      ' <span style="color:#1565c0; font-size:10px;">v' + ver + '</span>' +
      ' <span style="color:#64748b; font-size:10px;">· ' + _ebEsc(cat) + '</span>' +
    '</label>';
  }).join("");
  var bodyHtml =
    '<div style="font-size:11px; color:#64748b; margin-bottom:8px;">Select which tools to bundle into one JSON file.</div>' +
    '<div style="border:1px solid #e2e8f0; max-height:280px; overflow-y:auto; background:#fff;">' + rowsHtml + '</div>' +
    '<div style="margin-top:8px; display:flex; gap:8px; align-items:center; justify-content:flex-end; font-size:10px;">' +
    '<a href="#" data-tm-exp-all style="color:#1565c0; text-decoration:none; cursor:pointer;">All</a>' +
    '<a href="#" data-tm-exp-none style="color:#1565c0; text-decoration:none; cursor:pointer;">None</a>' +
    '</div>' +
    '<div style="margin-top:10px;">' +
    '<input type="text" id="tmExpBundleName" placeholder="Bundle name (optional, e.g. \'Alice Onboarding\')" style="width:100%; padding:7px; font-size:11px; border:1px solid #cbd5e1; box-sizing:border-box;">' +
    '</div>';
  var ov = showEliDialog({
    variant: "info", textAlign: "left", icon: "📦", title: "Export selected as bundle",
    body: bodyHtml,
    buttons: [
      { id: "btnTmExpDo", label: "📦 Export bundle", passthrough: true,
        style: "flex:1; background:#0d9488; color:#fff; font-weight:800;",
        onclick: function () {
          var checked = ov.querySelectorAll('input[data-tm-exp-id]:checked');
          var ids = Array.prototype.map.call(checked, function (cb) { return cb.getAttribute("data-tm-exp-id"); });
          if (!ids.length) { showToast("Select at least one tool.", "info"); return; }
          var nameInput = ov.querySelector("#tmExpBundleName");
          var bundleName = (nameInput && nameInput.value && nameInput.value.trim()) || "ELI Tool Bundle";
          var subset = tools.filter(function (t) { return ids.indexOf(t.id) !== -1; });
          var maxVer = subset.reduce(function (m, t) { return Math.max(m, Number(t.__version) || 0); }, 0);
          var payload = {
            schemaVersion: DATA_HUB_SCHEMA_VERSION,
            exportedAt: new Date().toISOString(),
            manifest: { name: bundleName, count: subset.length, tools: subset.map(function (t) { return t.id; }) },
            sectionVersions: { jsonTools: maxVer || 1 },
            sections: { jsonTools: subset },
          };
          var slug = bundleName.toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "bundle";
          var fname = slug + "-" + new Date().toISOString().slice(0, 10) + ".json";
          _dataHubTriggerDownload(fname, JSON.stringify(payload, null, 2));
          showToast("📦 Exported " + subset.length + " tool(s) as " + fname, "success");
          ov.remove();
        } },
      { id: "btnTmExpCancel", label: "Cancel", passthrough: true, style: "flex:1; margin-left:5px;",
        onclick: function () { ov.remove(); } },
    ],
  });
  ov.querySelector('[data-tm-exp-all]').onclick = function (e) {
    e.preventDefault();
    ov.querySelectorAll('input[data-tm-exp-id]').forEach(function (cb) { cb.checked = true; });
  };
  ov.querySelector('[data-tm-exp-none]').onclick = function (e) {
    e.preventDefault();
    ov.querySelectorAll('input[data-tm-exp-id]').forEach(function (cb) { cb.checked = false; });
  };
}
// Force reinstall — manifest-driven picker. Fetches the live manifest so the
// list shows EVERY published entry (tools + data) with its current install
// state. User picks any → markers cleared → entries reappear as available
// in the next update check.
//   For tool kinds:  set json_tools row's __version → 0 (manifest's vN
//                    appears as pending update)
//   For data kinds:  remove localStorage.eli_dataVer_<id>
// Does NOT delete IDB content — re-install merges over whatever's there.

functions._toolManagerForceReinstall:
function _toolManagerForceReinstall(installedTools) {
  var repo = window.ELI_UPDATE_REPO;
  var branch = window.ELI_UPDATE_BRANCH;
  var manifestName = window.ELI_UPDATE_MANIFEST;
  var GH_RAW_HOST = "raw.git" + "hubusercontent.com";
  var rawBlocked = false;
  try { rawBlocked = localStorage.getItem("eli_rawBlocked") === "1"; } catch (_) {}
  var ts = "?t=" + Date.now();
  var rawUrl = "https://" + GH_RAW_HOST + "/" + repo + "/" + branch + "/" + manifestName + ts;
  var cdnUrl = "https://cdn.jsdelivr.net/gh/" + repo + "@" + branch + "/" + manifestName + ts;
  var primaryUrl = rawBlocked ? cdnUrl : rawUrl;
  var fallbackUrl = rawBlocked ? null : cdnUrl;
  showToast("📥 Fetching manifest…");
  fetch(primaryUrl, { cache: "no-store" })
    .then(function (r) { if (!r.ok) throw new Error("manifest " + r.status); return r.json(); })
    .catch(function (e) {
      if (!fallbackUrl) throw e;
      return fetch(fallbackUrl, { cache: "no-store" }).then(function (r) {
        if (!r.ok) throw new Error("manifest " + r.status);
        return r.json();
      });
    })
    .then(function (mfst) { _tmShowFriPicker(mfst, installedTools); })
    .catch(function (e) {
      showToast("⚠️ Couldn't fetch manifest: " + (e.message || e), "error");
    });
}

functions._tmShowFriPicker:
function _tmShowFriPicker(mfst, installedTools) {
  var installedById = {};
  (installedTools || []).forEach(function (t) { if (t && t.id) installedById[t.id] = t; });
  var items = (mfst.tools || []).map(function (m) {
    var kind = m.kind || "tool";
    var state = "", color = "#94a3b8", inst, ver;
    if (kind === "tool") {
      inst = installedById[m.id];
      if (!inst) { state = "⌀ not installed"; color = "#94a3b8"; }
      else if (Number(inst.__version) >= Number(m.version)) { state = "✓ installed v" + inst.__version; color = "#16a34a"; }
      else { state = "🆙 v" + inst.__version + " → v" + m.version + " (update available)"; color = "#d97706"; }
    } else {
      ver = 0;
      try { ver = Number(localStorage.getItem("eli_dataVer_" + m.id)) || 0; } catch (_) {}
      if (ver === 0) { state = "⌀ not installed"; color = "#94a3b8"; }
      else if (ver >= Number(m.version)) { state = "✓ installed v" + ver; color = "#16a34a"; }
      else { state = "🆙 v" + ver + " → v" + m.version + " (update available)"; color = "#d97706"; }
    }
    return { id: m.id, kind: kind, label: m.label || m.id, category: m.category || "Uncategorized", state: state, color: color };
  });
  if (!items.length) { showToast("Manifest is empty.", "info"); return; }
  // Group by category
  var byCat = {};
  items.forEach(function (it) { (byCat[it.category] = byCat[it.category] || []).push(it); });
  var KNOWN_ORDER = ["Tools - ELI Core", "Admin", "Document", "Hygiene", "ELI Essentials", "Tools", "Uncategorized", "Data"];
  var cats = Object.keys(byCat).sort(function (a, b) {
    var ai = KNOWN_ORDER.indexOf(a), bi = KNOWN_ORDER.indexOf(b);
    if (ai !== -1 && bi !== -1) return ai - bi;
    if (ai !== -1) return -1; if (bi !== -1) return 1;
    return a.localeCompare(b);
  });
  var rowsHtml = cats.map(function (cat) {
    var section = '<div style="background:linear-gradient(135deg,#0f172a,#1e293b); color:#fff; padding:5px 10px; font-size:10px; font-weight:800; text-transform:uppercase; letter-spacing:0.5px;">' + _ebEsc(cat) + ' (' + byCat[cat].length + ')</div>';
    var rows = byCat[cat].map(function (item) {
      var ic = item.kind === "tool" ? "🧩" : "📦";
      return '<label style="display:block; padding:7px 10px; cursor:pointer; border-bottom:1px solid #f1f5f9; text-align:left;">' +
        '<input type="checkbox" data-tm-fri-kind="' + item.kind + '" data-tm-fri-id="' + _ebEsc(item.id) + '" style="margin-right:8px; vertical-align:middle; cursor:pointer;">' +
        '<span style="font-size:12px; font-weight:700; color:#0f172a;">' + ic + ' ' + _ebEsc(item.label) + '</span>' +
        '<div style="font-size:10px; color:' + item.color + '; margin:2px 0 0 24px;">' + item.state + '</div>' +
      '</label>';
    }).join("");
    return section + rows;
  }).join("");
  var bodyHtml =
    '<div style="font-size:11px; color:#64748b; margin-bottom:8px; text-align:left;">' +
    'Reset install markers for selected items. They\'ll appear as <strong>available to install</strong> in the next update check. ' +
    'Existing IDB content is NOT deleted — re-install merges over it (no data loss).</div>' +
    '<div style="border:1px solid #e2e8f0; max-height:340px; overflow-y:auto; background:#fff;">' + rowsHtml + '</div>' +
    '<div style="margin-top:8px; display:flex; gap:8px; justify-content:flex-end; font-size:10px;">' +
    '<a href="#" data-tm-fri-all style="color:#1565c0; text-decoration:none; cursor:pointer;">All</a>' +
    '<a href="#" data-tm-fri-none style="color:#1565c0; text-decoration:none; cursor:pointer;">None</a>' +
    '</div>';
  var ov = showEliDialog({
    variant: "warning", textAlign: "left", icon: "🔄", title: "Force reinstall",
    body: bodyHtml,
    buttons: [
      { id: "btnTmFriDo", label: "🔄 Reset markers", passthrough: true,
        style: "flex:1; background:#d97706; color:#fff; font-weight:800;",
        onclick: function () {
          var checked = ov.querySelectorAll('input[data-tm-fri-id]:checked');
          if (!checked.length) { showToast("Select at least one.", "info"); return; }
          var dataIds = [], toolIds = [];
          Array.prototype.forEach.call(checked, function (cb) {
            var kind = cb.getAttribute("data-tm-fri-kind");
            var id = cb.getAttribute("data-tm-fri-id");
            if (kind === "data") { try { localStorage.removeItem("eli_dataVer_" + id); } catch (_) {} dataIds.push(id); }
            else if (kind === "tool") { toolIds.push(id); }
          });
          var toolUpdates = toolIds.map(function (id) {
            return loadFeatureDataByIds(STORE_JSON_TOOLS, [id]).then(function (rows) {
              if (rows && rows[0]) {
                rows[0].__version = 0;
                return saveFeatureRow(STORE_JSON_TOOLS, rows[0]);
              }
            });
          });
          Promise.all(toolUpdates).then(function () {
            ["eli_pendingUpdates", "eli_availableTools", "eli_updateNoticeSig", "eli_lastUpdateCheck"].forEach(function (k) {
              try { localStorage.removeItem(k); } catch (_) {}
            });
            showToast("✓ Reset " + (dataIds.length + toolIds.length) + " marker(s). Reload ELI to see them in install dialog.", "success");
            ov.remove();
          });
        } },
      { id: "btnTmFriCancel", label: "Cancel", passthrough: true, style: "flex:1; margin-left:5px;",
        onclick: function () { ov.remove(); } },
    ],
  });
  ov.querySelector('[data-tm-fri-all]').onclick = function (e) {
    e.preventDefault();
    ov.querySelectorAll('input[data-tm-fri-id]').forEach(function (cb) { cb.checked = true; });
  };
  ov.querySelector('[data-tm-fri-none]').onclick = function (e) {
    e.preventDefault();
    ov.querySelectorAll('input[data-tm-fri-id]').forEach(function (cb) { cb.checked = false; });
  };
}

functions._toolManagerInstall:
function _toolManagerInstall(_unused, listWrap, actionsWrap) {
  var inp = document.createElement("input");
  inp.type = "file"; inp.accept = ".json"; inp.style.display = "none";
  inp.onchange = function (e) {
    var f = e.target.files && e.target.files[0]; if (!f) return;
    var reader = new FileReader();
    reader.onload = function (evt) {
      var json;
      try { json = JSON.parse(evt.target.result); }
      catch (err) { showToast("⚠️ Invalid JSON: " + (err && err.message ? err.message : "parse error"), "error"); return; }
      _dataHubImportFromJson(json, { allowedKeys: ["jsonTools"], actions: { jsonTools: "merge" } }).then(function (res) {
        if (res.ok) {
          showToast("✅ Installed " + (res.results[0] && res.results[0].rows ? res.results[0].rows : "?") + " tool(s)", "success");
          _toolManagerRender(listWrap, actionsWrap);
        } else {
          showToast("⚠️ Install errors: " + res.errors.join(", "), "error");
        }
      });
    };
    reader.readAsText(f);
  };
  document.body.appendChild(inp); inp.click();
  setTimeout(function () { try { document.body.removeChild(inp); } catch (_) { } }, 1000);
}

functions._toolManagerToggle:
function _toolManagerToggle(toolId, listWrap, actionsWrap) {
  Promise.all([
    loadFeatureDataByIds(STORE_JSON_TOOLS, ["__enabled"]),
    loadFeatureDataByIds(STORE_JSON_TOOLS, [toolId]),
  ]).then(function (results) {
    var enabledRow = (results[0] && results[0][0]) || null;
    var toolRow = (results[1] && results[1][0]) || null;
    if (!toolRow) { showToast("Tool not found: " + toolId, "error"); return; }
    var enabled = (enabledRow && Array.isArray(enabledRow.ids)) ? enabledRow.ids.slice() : null;
    var willEnable, newEnabled;
    if (enabled === null) {
      return loadFeatureData(STORE_JSON_TOOLS).then(function (allRows) {
        var ids = (allRows || [])
          .filter(function (r) { return r && r.id && String(r.id).indexOf("__") !== 0; })
          .map(function (r) { return r.id; });
        newEnabled = ids.filter(function (id) { return id !== toolId; });
        willEnable = false;
        return _tmApplyToggle(newEnabled, willEnable, toolRow);
      });
    }
    var idx = enabled.indexOf(toolId);
    if (idx === -1) { newEnabled = enabled.concat([toolId]); willEnable = true; }
    else { newEnabled = enabled.slice(0, idx).concat(enabled.slice(idx + 1)); willEnable = false; }
    return _tmApplyToggle(newEnabled, willEnable, toolRow);
  }).then(function () {
    _toolManagerRender(listWrap, actionsWrap);
  });
}

functions._tmApplyToggle:
function _tmApplyToggle(newEnabledIds, willEnable, toolRow) {
  var p = saveFeatureRow(STORE_JSON_TOOLS, { id: "__enabled", ids: newEnabledIds });
  if (willEnable && toolRow.functions) {
    try {
      Object.keys(toolRow.functions).forEach(function (fnName) {
        var src = toolRow.functions[fnName];
        if (typeof src === "string" && src.length) {
          window[fnName] = new Function("return (\n" + src + "\n);")();
        }
      });
    } catch (e) { if (typeof ELI_DEBUG !== "undefined" && ELI_DEBUG) console.warn("[ELI] toggle-enable eval error:", e); }
  }
  return p.then(function () {
    if (!toolRow.catalog || !toolRow.catalog.id) return;
    if (willEnable) {
      var catalogRow = Object.assign({}, toolRow.catalog, { source: "tool:" + toolRow.id });
      return saveFeatureRow(STORE_CATALOG, catalogRow);
    } else {
      return deleteFeatureRow(STORE_CATALOG, toolRow.catalog.id);
    }
  }).then(function () {
    if (typeof _eliInvalidateCatalogCache === "function") _eliInvalidateCatalogCache();
    if (typeof _eliEnsureCatalogLoaded === "function") {
      return _eliEnsureCatalogLoaded().then(function () {
        try { if (typeof window.refreshDashboardGrid === "function") window.refreshDashboardGrid(); } catch (_) {}
      });
    }
  }).then(function () {
    showToast(willEnable ? "✓ Enabled: " + toolRow.id : "🔕 Disabled: " + toolRow.id, willEnable ? "success" : "info");
  });
}

functions._toolManagerRemove:
function _toolManagerRemove(toolId, listWrap, actionsWrap) {
  var ovRm = showEliDialog({
    variant: "danger", icon: "🗑️", title: "Remove tool?",
    body: "This will uninstall <strong>" + _ebEsc(toolId) + "</strong> and remove its dashboard tile.<br><br>You can re-install it later by uploading the JSON.",
    buttons: [
      { id: "btnTmCancel", label: "Cancel", cls: "btn-platinum-config", style: "flex:1; margin-right:6px;",
        onclick: function () { ovRm.remove(); } },
      { id: "btnTmOk", label: "Remove", style: "flex:1; margin-left:6px; background:#dc2626; color:#fff; font-weight:bold;",
        onclick: function () {
          ovRm.remove();
          loadFeatureData(STORE_JSON_TOOLS).then(function (rows) {
            var keep = (rows || []).filter(function (r) { return !(r && r.id === toolId); });
            return saveFeatureData(STORE_JSON_TOOLS, keep);
          }).then(function () {
            if (typeof _dataHubCascadeRemoveToolCatalog === "function") {
              return _dataHubCascadeRemoveToolCatalog([toolId]);
            }
          }).then(function () {
            showToast("🗑️ Removed: " + toolId, "success");
            _toolManagerRender(listWrap, actionsWrap);
          });
        } },
    ],
  });
}

functions._toolManagerForceCheck:
function _toolManagerForceCheck(listWrap, actionsWrap) {
  if (!window._eliCheckForToolUpdates) {
    showToast("Update system not available — main file may be out of date.", "error");
    return;
  }
  if (typeof showToast === "function") showToast("🔄 Checking for updates…");
  window._eliCheckForToolUpdates({ force: true }).then(function () {
    _toolManagerRender(listWrap, actionsWrap);
  });
}

functions._toolManagerInstallNew:
function _toolManagerInstallNew(toolId, listWrap, actionsWrap) {
  var entry = (window._eliAvailableTools || []).filter(function (a) { return a.id === toolId; })[0];
  if (!entry) { showToast("No available entry for " + toolId, "info"); return; }
  if (!window._eliApplyToolUpdate) {
    showToast("Update system not available — main file may be out of date.", "error");
    return;
  }
  if (typeof showToast === "function") showToast("⬇️ Installing " + entry.label + " v" + entry.version + "…");
  window._eliApplyToolUpdate(entry).then(function () {
    // Drop from available list (it's now installed)
    if (Array.isArray(window._eliAvailableTools)) {
      window._eliAvailableTools = window._eliAvailableTools.filter(function (a) { return a.id !== toolId; });
    }
    showToast("✅ Installed " + entry.label + " v" + entry.version, "success");
    _toolManagerRender(listWrap, actionsWrap);
  }).catch(function (e) {
    showToast("⚠️ Install failed: " + (e.message || e), "error");
  });
}

functions._toolManagerInstallAllNew:
function _toolManagerInstallAllNew(listWrap, actionsWrap) {
  var avail = (window._eliAvailableTools || []).slice();
  if (!avail.length) { showToast("Nothing to install.", "info"); return; }
  if (!window._eliApplyToolUpdate) {
    showToast("Update system not available — main file may be out of date.", "error");
    return;
  }
  showToast("⬇️ Installing " + avail.length + " new tool(s)…");
  function next(i, ok, fail) {
    if (i >= avail.length) {
      showToast(fail.length ? ("⚠️ " + ok.length + " installed, " + fail.length + " failed") : ("✅ " + ok.length + " new tool(s) installed"), fail.length ? "error" : "success");
      _toolManagerRender(listWrap, actionsWrap);
      return;
    }
    var a = avail[i];
    window._eliApplyToolUpdate(a).then(function () {
      ok.push(a.id);
      if (Array.isArray(window._eliAvailableTools)) {
        window._eliAvailableTools = window._eliAvailableTools.filter(function (x) { return x.id !== a.id; });
      }
      next(i + 1, ok, fail);
    }, function (e) {
      console.error("[ELI] new install failed for", a.id, e);
      fail.push(a.id);
      next(i + 1, ok, fail);
    });
  }
  next(0, [], []);
}

functions._toolManagerApplyCdnUpdate:
function _toolManagerApplyCdnUpdate(toolId, listWrap, actionsWrap) {
  var pending = (window._eliPendingUpdates || []).filter(function (p) { return p.id === toolId; })[0];
  if (!pending) {
    showToast("No pending update for " + toolId, "info");
    return;
  }
  if (!window._eliApplyToolUpdate) {
    showToast("Update system not available — main file may be out of date.", "error");
    return;
  }
  if (typeof showToast === "function") showToast("⬇️ Downloading " + toolId + " v" + pending.version + "…");
  window._eliApplyToolUpdate(pending).then(function () {
    showToast("✅ " + toolId + " updated to v" + pending.version, "success");
    _toolManagerRender(listWrap, actionsWrap);
  }).catch(function (e) {
    showToast("⚠️ Update failed: " + (e.message || e), "error");
  });
}

functions._toolManagerApplyAllCdnUpdates:
function _toolManagerApplyAllCdnUpdates(listWrap, actionsWrap) {
  var pending = (window._eliPendingUpdates || []).slice();
  if (!pending.length) { showToast("Nothing to update.", "info"); return; }
  if (!window._eliApplyToolUpdate) {
    showToast("Update system not available — main file may be out of date.", "error");
    return;
  }
  showToast("⬇️ Updating " + pending.length + " tool(s)…");
  // Apply sequentially so each import completes before the next starts.
  // (Tool Manager updating itself is fine — the loader re-evals all functions
  //  including this one, but the in-flight loop variable references stay valid.)
  function next(i, ok, fail) {
    if (i >= pending.length) {
      showToast(fail.length ? ("⚠️ " + ok.length + " updated, " + fail.length + " failed") : ("✅ " + ok.length + " tool(s) updated"), fail.length ? "error" : "success");
      _toolManagerRender(listWrap, actionsWrap);
      return;
    }
    var p = pending[i];
    window._eliApplyToolUpdate(p).then(function () {
      ok.push(p.id);
      next(i + 1, ok, fail);
    }, function (e) {
      console.error("[ELI] update failed for", p.id, e);
      fail.push(p.id);
      next(i + 1, ok, fail);
    });
  }
  next(0, [], []);
}
